package com.bank.merge;

import java.util.logging.Logger;

public class StreamMergeAuditor {

    private static final Logger log = Logger.getLogger(StreamMergeAuditor.class.getName());

    public boolean isInterleave(String s1, String s2, String s3) {
        int m = s1.length(), n = s2.length();
        if (m + n != s3.length()) {                    // length must match exactly
            log.warning("Length mismatch; not an interleaving");
            return false;
        }
        boolean[][] dp = new boolean[m + 1][n + 1];
        dp[0][0] = true;                               // empty + empty = empty
        for (int i = 0; i <= m; i++) {
            for (int j = 0; j <= n; j++) {
                if (i > 0 && dp[i - 1][j] && s1.charAt(i - 1) == s3.charAt(i + j - 1)) {
                    dp[i][j] = true;                   // last char came from s1
                }
                if (j > 0 && dp[i][j - 1] && s2.charAt(j - 1) == s3.charAt(i + j - 1)) {
                    dp[i][j] = true;                   // last char came from s2
                }
            }
        }
        boolean result = dp[m][n];
        log.info(() -> "isInterleave = " + result);
        return result;
    }
}
